import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as t,a as r}from"./chunks/M-S-LCS15b3.Bke3gG24.js";import{_ as o}from"./chunks/EN.P9aPnFBv.js";import{_ as s,o as n,c as l,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Altre opzioni varie","description":"","frontmatter":{"source_hash":"87f439d0b6","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/use/misc.md","filePath":"it/use/misc.md"}'),d={name:"it/use/misc.md"};function c(m,a,u,g,v,b){return n(),l("div",null,[...a[0]||(a[0]=[p('<p>In questo menu sono disponibili altre opzioni.<br> Se sono nascoste qui, probabilmente è perché non ti servirà modificarle tutti i giorni, oppure perché dovresti lasciarle come sono salvo indicazioni diverse.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>   Impostazioni Meno Usate<br>    Altre opzioni</p></div><h5 id="run-collector-in-foreground" tabindex="-1">Eseguire Collector in primo piano <a class="header-anchor" href="#run-collector-in-foreground" aria-label="Permalink to &quot;Eseguire Collector in primo piano {#run-collector-in-foreground}&quot;">​</a></h5><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Da quando è stato abbandonato il supporto ad Android 7 (<a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.12" target="_blank" rel="noreferrer">12 luglio 2026</a>) questa opzione non è più disattivabile.</p></div><p>Su Android 8.0 e successivi (la versione minima supportata) xDrip esegue sempre il collector come servizio in primo piano, per evitare che Android lo metta in sospensione. Viene quindi sempre mostrata una notifica persistente con il grafico, visibile anche sulla schermata di blocco.</p><p>Se preferisci non mostrare il grafico, l&#39;opzione <code>Notifica Persistente Compatta</code> nello stesso menu mostra solo il valore attuale della glicemia.</p><div class="admonition xdripitem"><p class="admonition-title">Notifica Persistente Compatta <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Abilita per nascondere il grafico nelle notifiche e visualizzare solo il valore attuale di glucosio.</p></div><img src="'+t+'" style="zoom:75%;"><h5 id="engineering-mode" tabindex="-1">Modalità Sviluppatore <a class="header-anchor" href="#engineering-mode" aria-label="Permalink to &quot;Modalità Sviluppatore {#engineering-mode}&quot;">​</a></h5><p>Attiva funzioni potenzialmente pericolose o non testate. Non serve attivarla per riavviare un trasmettitore G5 o un vecchio G6 (quelli nuovi, chiamati Firefly, non possono essere riavviati). In realtà non hai bisogno di attivarla.</p><div class="admonition xdripitem"><p class="admonition-title">Modalità Sviluppatore <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Consente di cambiare le impostazioni più pericolose: a vostro rischio e pericolo!</p></div><p>Per attivare la Modalità Sviluppatore inserisci o pronuncia il trattamento <code>enable engineering mode</code>.</p><p>Ogni mese ti verrà ricordato che la Modalità Sviluppatore è attiva. Assicurati di averne davvero bisogno, altrimenti tienila disattivata.</p><img src="'+r+'" style="zoom:52%;"><h5 id="battery-optimization-prompt" tabindex="-1">Richiesta di Ottimizzazione della Batteria <a class="header-anchor" href="#battery-optimization-prompt" aria-label="Permalink to &quot;Richiesta di Ottimizzazione della Batteria {#battery-optimization-prompt}&quot;">​</a></h5><p>Va lasciata <strong>disattivata</strong>. xDrip deve essere <a href="./../install/install.html#authorize-background-activity">escluso dall&#39;ottimizzazione</a> e non deve esserne soggetto.</p><div class="admonition xdripitem"><p class="admonition-title">Richiesta di Ottimizzazione della Batteria <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Con Android 6+ verifica che l&#39;ottimizzazione della batteria sia spenta. Raccomandato</p></div><h5 id="samsung-workarounds" tabindex="-1">Samsung Workarounds <a class="header-anchor" href="#samsung-workarounds" aria-label="Permalink to &quot;Samsung Workarounds {#samsung-workarounds}&quot;">​</a></h5><p>Rinominato Wake Workarounds perché anche altri dispositivi non sono conformi.</p><h5 id="wake-workarounds" tabindex="-1">Wake Workarounds <a class="header-anchor" href="#wake-workarounds" aria-label="Permalink to &quot;Wake Workarounds {#wake-workarounds}&quot;">​</a></h5><p>Corregge una non conformità di alcuni dispositivi Android; ora è predefinito per Samsung, Xiaomi, OnePlus, Oppo e Huawei.<br> Va tenuto <strong>attivato</strong>.</p><div class="admonition xdripitem"><p class="admonition-title">Samsung Workaround <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Usa workaround per evitare il comportamento non standard a Android degli telefonini Samsung. Senza questo, di solito non si riesce a ricevere dati.</p></div><p>Uso eccessivo Wakelocks non è necessario. Si tratta di messaggi di &quot;risveglio&quot; aggiuntivi che xDrip invia al dispositivo Android per impedirgli di entrare in sospensione.</p><div class="admonition xdripitem"><p class="admonition-title">Uso eccessivo Wakelocks <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Vecchi wakelocks gratuiti possono consumare la batteria, ma potrebbero essere necessari per NightWatch o Android Wear</p></div><p>Mostra Valori Predetti (vecchio metodo) è deprecato. Usa la <a href="./predictions.html">simulazione predittiva</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Mostra Valori Predetti <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Vecchio metodo - Non consigliato! Tenta di prevedere letture ogni minuto sulla base di pochi valori precedenti.</p></div><p>Proper Ongoing è indispensabile per i dispositivi con Android 8 e successivi. Visibile solo con la Modalità Sviluppatore attivata.</p><div class="admonition xdripitem"><p class="admonition-title">Proper Ongoing <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p>Use proper ongoing notification. Disabling this causes collector problems on Android 8+</p></div><h5 id="out-of-process-algorithm" tabindex="-1">Algoritmo Out of Process <a class="header-anchor" href="#out-of-process-algorithm" aria-label="Permalink to &quot;Algoritmo Out of Process {#out-of-process-algorithm}&quot;">​</a></h5><p>L&#39;<a href="./OOP.html">algoritmo Out Of Process</a> permette di integrare un plugin esterno che fornisce valori glicemici simili a quelli del produttore per i sensori Libre, o che decodifica le informazioni del sensore Libre 2 EU.<br> Se l&#39;app esterna non è presente sul telefono o non fornisce le informazioni, xDrip non mostrerà la glicemia.</p><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p>Questa opzione va attivata solo se usi un algoritmo Out Of Process versione 1 (OOP1).<br> Deve essere disattivata per OOP2.</p></div><div class="admonition xdripitem"><p class="admonition-title">Algoritmo Libre OOP. <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Usa un algoritmo OOP. (Libre Bluetooth/NFC/LibreAlarm)</p></div><h5 id="oop2" tabindex="-1">OOP2 <a class="header-anchor" href="#oop2" aria-label="Permalink to &quot;OOP2 {#oop2}&quot;">​</a></h5><p>OOP2 è indispensabile per gestire i dati dei sensori Libre 14 days US e Libre 2/2+ EU.</p><div class="admonition xdripitem"><p class="admonition-title">Calibrazione dell&#39;algoritmo OOP2.</p><p> Applica le calibrazioni xDrip sui dati da OOP2.</p></div><p>Puoi usare OOP2 in modi diversi:</p><ul><li>No calibration genera valori simili a quelli del produttore (modalità nativa) senza bisogno di calibrare. Non significa che i risultati non siano calibrati (grezzi): viene applicato un algoritmo simile a quello del produttore (come il lettore Libre 1).</li><li>Calibrate based on raw usa i dati grezzi del sensore (senza correzione della temperatura), come per il Libre 1. Userai l&#39;algoritmo di calibrazione di xDrip. <strong>Impostazione predefinita.</strong></li><li>Calibrate based on glucose ti permette di applicare la calibrazione di xDrip ai valori nativi. I dati grezzi vengono trasformati con l&#39;algoritmo simile a quello del produttore e poi passati all&#39;algoritmo di calibrazione di xDrip.</li></ul><div class="admonition xdripitem"><p class="admonition-title">Calibrazione dell&#39;algoritmo OOP2.</p><p> No calibration       ○<br>  Calibrate based on raw   ●<br>  Calibrate based on glucose (experimental)  ○</p></div><p>Liscia dati Libre fa la media su 5 misure. Questo ritarda anche le letture.<br> Se questa opzione non porta il miglioramento atteso, prova anche <a href="./display.html#smooth-sensor-noise">Liscia il rumore del sensore</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Liscia dati Libre. <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Usa una media di 5 punti per ottenere risultati Libre meno rumorosi.</p></div><p>Recupera cronologia Libre è necessario per i bridge BluCon. Gli altri bridge recuperano i dati mancanti automaticamente.</p><div class="admonition xdripitem"><p class="admonition-title">Recupera cronologia Libre <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Recupera la cronologia dal dispositivo Blukon quando si ricollega al sensore.</p></div><p>La visualizzazione Libre a un minuto è ancora in sviluppo. xDrip mostra i valori glicemici ogni 5 minuti. Con la sorgente dati <a href="./../install/li3.html">Li3</a>, quando è attivata, le letture vengono salvate ogni minuto.</p><div class="admonition xdripitem"><p class="admonition-title">Libre 1-minuto <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Accetta i dati ad intervalli di un minuto da Libre. Riavvia il telefono per attivare la modifica.</p></div><h5 id="li3" tabindex="-1">Li3 <a class="header-anchor" href="#li3" aria-label="Permalink to &quot;Li3 {#li3}&quot;">​</a></h5><p>Le impostazioni Li3 (Account ID, Official app, Smooth Li3 readings) sono spiegate nella pagina <a href="./../install/li3.html#li3-settings">Li3</a>.</p><h5 id="1-min-inter-app-broadcast" tabindex="-1">1-min Inter-app broadcast <a class="header-anchor" href="#1-min-inter-app-broadcast" aria-label="Permalink to &quot;1-min Inter-app broadcast {#1-min-inter-app-broadcast}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">1-min Inter-app broadcast <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Accept data at one-minute intervals from Inter-app broadcast. Reboot your phone for changes to take effect.</p></div><p>Accetta letture ogni minuto invece che ogni 5 minuti dalla sorgente dati <a href="./../install/640_670.html">Inter-app broadcast</a>. Riavvia il telefono dopo averla modificata. Dal <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.09.09" target="_blank" rel="noreferrer">9 settembre 2026</a> non richiede più la Modalità Sviluppatore (prima si chiamava &quot;640G/Eversense 1-minute&quot;).</p><p>L&#39;opzione qui sotto è sempre disattivata (in grigio) nell&#39;app: non può essere attivata.</p><div class="admonition xdripitem"><p class="admonition-title">SOLO SIMULAZIONE - NON USARE IN PRODUZIONE <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',53)])])}const x=s(d,[["render",c]]);export{_ as __pageData,x as default};
